// Base Organization structured data (schema.org), shared by the sitewide
// JSON-LD in PublicLayout and extended with aggregateRating/review on Home.
//
// Typed as both Organization and LocalBusiness so the entry qualifies for
// Google's local pack (Sri Lanka searches) as well as general knowledge-panel
// treatment. Fields here must match what's visibly shown on the site (Google
// flags structured data that doesn't match page content) — that's why there's
// no street address or geo coordinates: the public site only ever shows
// "Negombo, Sri Lanka", not the full registered address from siteLetterhead.
export function buildOrganizationSchema() {
    return {
        '@context': 'https://schema.org',
        '@type': ['Organization', 'LocalBusiness'],
        '@id': `${SITE_URL}/#organization`,
        name: SITE_NAME,
        url: SITE_URL,
        logo: `${SITE_URL}/favicon.svg`,
        image: DEFAULT_OG_IMAGE,
        email: siteContact.email,
        telephone: siteContact.phone,
        priceRange: '$$',
        address: {
            '@type': 'PostalAddress',
            addressLocality: 'Negombo',
            addressRegion: 'Western Province',
            addressCountry: 'LK',
        },
        openingHoursSpecification: {
            '@type': 'OpeningHoursSpecification',
            dayOfWeek: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'],
            opens: '09:00',
            closes: '18:00',
        },
        areaServed: ['Sri Lanka', 'Worldwide'],
        sameAs: [siteSocial.github, siteSocial.facebook, siteSocial.linkedin, siteSocial.instagram],
        description:
            'JayarathnaTech Solutions is a software company based in Negombo, Sri Lanka, building web applications, e-commerce platforms, and custom software for clients in Sri Lanka and internationally.',
    }
}

// BreadcrumbList structured data — reflects the page's position in the site
// hierarchy for rich-result breadcrumbs. `items` should run from the home
// page to the current page, e.g. [{ name: 'Home', url: '/' }, { name: 'Services', url: '/services' }].
export function buildBreadcrumbSchema(items: { name: string; url: string }[]) {
    return {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        itemListElement: items.map((item, index) => ({
            '@type': 'ListItem',
            position: index + 1,
            name: item.name,
            item: `${SITE_URL}${item.url}`,
        })),
    }
}
